import math

def get_divisors(n):
    divs = []
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.append(i)
            if i*i != n:
                divs.append(n // i)
    return sorted(divs)

def sigma(n):
    s = 0
    for d in get_divisors(n):
        s += d
    return s

def is_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.sqrt(n))
    return sqrt_n * sqrt_n == n

def solve_permutation(divisors):
    # This is a complex NP-like problem. We use a simple backtracking/search attempt.
    # For small sets of divisors, this might work.

    n = len(divisors)

    def backtrack(current_sum, used_divisors, path):
        if len(path) == n:
            return True

        for i in range(n):
            if i not in used_divisors:
                next_divisor = divisors[i]
                next_sum = current_sum + next_divisor

                # Check if the new prefix sum is a square
                if is_square(next_sum):
                    used_divisors.add(i)
                    path.append(next_divisor)

                    if backtrack(next_sum, used_divisors, path):
                        return True

                    path.pop()
                    used_divisors.remove(i)
        return False

    # Try all possible starting points, since the order matters
    for i in range(n):
        a1 = divisors[i]
        if is_square(a1):
            used = {i}
            path = [a1]
            if backtrack(a1, used, path):
                return True

    return False

