import math

def sigma(n):
    if n == 1:
        return 1

    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    sum_divisors = 1
    for p, a in factors.items():
        sum_divisors *= (p**(a + 1) - 1) // (p - 1)
    return sum_divisors

def is_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.sqrt(n))
    return sqrt_n * sqrt_n == n

